import { Component, input } from '@angular/core';
import { NzBadgeModule } from 'ng-zorro-antd/badge';

export type HrmBadgeStatus = 'success' | 'processing' | 'default' | 'error' | 'warning';

/** hrm-badge — bọc nz-badge. Dạng count (bọc phần tử) hoặc status dot + text.
 *  shape='square': bong bóng số bo góc nhẹ (radius-sm) thay vì tròn — hợp hiển thị số trong bảng. */
@Component({
  selector: 'hrm-badge',
  imports: [NzBadgeModule],
  template: `
    @if (status()) {
      <nz-badge [nzStatus]="status()!" [nzText]="text()"></nz-badge>
    } @else {
      <nz-badge [nzCount]="count()" [nzShowZero]="showZero()" [nzDot]="dot()" [nzOverflowCount]="overflowCount()">
        <ng-content />
      </nz-badge>
    }
  `,
  host: { class: 'hrm-badge', '[attr.data-shape]': 'shape()' },
  styles: [`
:host([data-shape='square']) ::ng-deep .ant-badge-count { border-radius: var(--radius-sm); }
  `],
})
export class HrmBadge {
  readonly count = input<number>(0);
  readonly showZero = input(false);
  readonly dot = input(false);
  readonly overflowCount = input(99);
  readonly status = input<HrmBadgeStatus | null>(null);
  readonly text = input('');
  /** 'default' = bong bóng tròn; 'square' = bo góc nhẹ (hợp số trong bảng). */
  readonly shape = input<'default' | 'square'>('default');
}
